-- 200 个驻场人员：每个企业 25 个；前 7 个企业分别分配到两个工厂，第 8 个企业使用一个工厂。
-- 身份证号按 18 位身份证校验码生成，序号 001 至 200 唯一。
INSERT INTO resident_factory (
    id, name, phone, id_card, factory_id, create_by, create_time,
    update_by, update_time, deleted, enterprise_id
)
WITH RECURSIVE seq (n) AS (
    SELECT 1
    UNION ALL
    SELECT n + 1
    FROM seq
    WHERE n < 200
)
SELECT
    231000000000000000 + n,
    CONCAT('测试驻场', LPAD(n, 3, '0')),
    CONCAT('13800000', LPAD(n, 3, '0')),
    CONCAT(
        '11010519900101',
        LPAD(n, 3, '0'),
        SUBSTRING(
            '10X98765432',
            MOD(
                120
                + 8 * FLOOR(n / 100)
                + 4 * FLOOR(MOD(n, 100) / 10)
                + 2 * MOD(n, 10),
                11
            ) + 1,
            1
        )
    ),
    CASE
        WHEN CEIL(n / 25) <= 7 THEN
            221000000000000000
            + ((CEIL(n / 25) - 1) * 2)
            + IF(MOD(n - 1, 25) + 1 <= 12, 1, 2)
        ELSE 221000000000000015
    END,
    201000000000000001,
    DATE_ADD('2026-09-01 10:00:00', INTERVAL n MINUTE),
    201000000000000001,
    DATE_ADD('2026-09-01 10:00:00', INTERVAL n MINUTE),
    1,
    CAST(211000000000000000 + CEIL(n / 25) AS CHAR)
FROM seq;
